 const selected=experimentSelected;
 // The standard transition always shows the selected design's original protein.
 // The separate simulation button explicitly opens the follow-up complex.
 if(jobsForVisualization().some(j=>j.candidate_id===selected)){showVisualizationSource(selected);}
 else{molecularEvidence.clear();molecularEvidence.setResearch(current);$('evidence-source-name').textContent='Design prediction';$('evidence-original').hidden=true;updateVisualizationSources();$('evidence-source-select').value='design';if(selected)molecularEvidence.focusCandidate(selected);}
