function updateVisualizationSources(){const select=$('evidence-source-select'),previous=select.value;select.innerHTML='<option value="design">Design prediction</option>'+jobsForVisualization().map(j=>`<option value="${escapeHtml(j.candidate_id)}">Simulation · ${escapeHtml(j.candidate_id)}</option>`).join('');select.value=[...select.options].some(o=>o.value===previous)?previous:'design';}
