function showVisualizationSource(id){if(!current)return;const job=jobsForVisualization().find(j=>j.candidate_id===id);molecularEvidence.clear();if(job){molecularEvidence.setResearch({...current,visualization_run:job.visualization_run,visualization_choices:[job.candidate_id],rendered:[job.candidate_id]});molecularEvidence.focusCandidate(job.candidate_id);$('evidence-source-name').textContent='Independent Boltz-2 simulation · '+job.candidate_id;$('evidence-original').hidden=false;}else{molecularEvidence.setResearch(current);$('evidence-source-name').textContent='Design prediction';$('evidence-original').hidden=true;}updateVisualizationSources();$('evidence-source-select').value=job?id:'design';}
